// CALIPER Tier-Based Procedural Asset Library (1,200 Models)
// 10 Categories x 6 Quality Tiers x 20 Models each
import * as THREE from 'three';
import * as BufferGeometryUtils from 'three/addons/utils/BufferGeometryUtils.js';

export function tagGeometry(geom, r = 0.6, g = 0.6, b = 0.6) {
  if (!geom || !geom.attributes || !geom.attributes.position) return geom;
  const count = geom.attributes.position.count;
  const colors = new Float32Array(count * 3);
  for (let i = 0; i < count; i++) {
    colors[i * 3] = r;
    colors[i * 3 + 1] = g;
    colors[i * 3 + 2] = b;
  }
  geom.setAttribute('color', new THREE.BufferAttribute(colors, 3));
  return geom;
}

export function mergeGeometries(geoms, T = THREE) {
  const clean = (geoms || []).filter(g => g && g.attributes && g.attributes.position);
  if (clean.length === 0) return new THREE.BufferGeometry();
  
  // Ensure all parts have color attribute before merging
  clean.forEach(g => {
    if (!g.attributes.color) {
      tagGeometry(g, 0.65, 0.65, 0.65);
    }
  });

  if (clean.length === 1) return clean[0];
  const merged = BufferGeometryUtils.mergeGeometries(clean, false);
  return merged || clean[0];
}


